import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第六章","description":"《正易心法》第六章——消息卦画，无止于辞：卦辞只是卦义的粗略截面，须于辞外见意，方审《易》道。","frontmatter":{"title":"正易心法·第六章","description":"《正易心法》第六章——消息卦画，无止于辞：卦辞只是卦义的粗略截面，须于辞外见意，方审《易》道。","category":"guide","aliases":["正易心法第六章","消息卦画无止于辞","辞外见意"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-06.md","filePath":"yijing/zheng-yi-xin-fa/chapter-06.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-06.md"},f=d({...c,setup(u){const o=[{id:"z6-01",label:"一、无止于辞",showLabel:!0,sentences:[["消息卦画，无止于辞。",{text:"辞外见意",glossary:"ciwaiJianyi"},"，方",{text:"审",glossary:"shen"},"《易》道。"]],note:["卦画中阴阳消息的道理，不止步于文辞；能在文辞之外看到意涵，才算真正明察《易》道。（这是第六章的总纲，也是前五章理论的第一次方法论示范。）"]},{id:"z6-02",label:"二、特系大略之辞",showLabel:!0,sentences:[["系辞，特系以吉凶",{text:"大略之辞",glossary:"dalueZhici"},"而已，非谓六画之义尽于是也。"]],note:["系在卦上的文辞，只不过是对吉凶的粗略概括，并非说六爻卦画的全部意义就尽于此。（「特」是只、不过；「系辞」在这里指系在卦爻下的辞，不是篇名。）"]},{id:"z6-03",label:"三、数字岂能尽义",showLabel:!0,sentences:[["如大有系以元亨，大壮系以利贞。此数字，果足以尽二卦之义乎？"]],note:["比如大有卦只系了「元亨」两字，大壮卦只系了「利贞」两字——这几个字，真的足以穷尽这两卦的全部意义吗？（大有是上离下乾「日在天上」，大壮是上震下乾「雷在天上」，卦画结构完全不同，处境与警示也截然不同，而卦辞都只有两个字。）"]},{id:"z6-04",label:"四、辞外之意",showLabel:!0,sentences:[["要须辞外见意可也。辞外之意，如乾九二“见龙在田”，上九“亢龙有悔”，"]],note:["必须要在文辞之外看到意涵才行。辞外之意，比如乾卦九二「见龙在田」、上九「亢龙有悔」——辞说的是「龙出现在田野」「飞得太高的龙会后悔」，象说的是阳气从地下升至地面、阳极必阴的消息铁律，不是一个关于龙的故事，也不是道德劝诫。"]},{id:"z6-05",label:"五、辟师之喻",showLabel:!0,sentences:[["辟师之上不动如地，内趋变如水，"]],note:["又如师卦：上卦坤不动如大地，下卦坎内趋变动如流水。（师卦䷆上坤下坎——辟（君主）居上如地载物，师（军队）居下如水无常形。外静内动，正是用兵之道的最高境界；这也是《孙子兵法》「动如雷霆，静如山岳」的易学根源。）"]},{id:"z6-06",label:"六、辞所不能该",showLabel:!0,sentences:[["无穷好意，如此类不可概举，皆是辞之所不能",{text:"该",glossary:"gai"},"也。"]],note:["这些无穷的妙义，此类例子不可一一列举，都是文辞所不能完全涵盖的。（「该」通「赅」，完备涵盖。辞是卦义的截面，卦画是卦义的全体——就像用一张照片描述一个人：照片能捕捉某一瞬间，但人的全部生命不在照片里。）"]}],i=[{id:"ciwaiJianyi",term:"辞外见意",pinyin:"cí wài jiàn yì",meaning:"在文辞之外看到意涵。超越文字，直观卦画深意。"},{id:"shen",term:"审",pinyin:"shěn",meaning:"细察、明辨。「方审《易》道」即才能真正明察《易》道。"},{id:"dalueZhici",term:"大略之辞",pinyin:"dà lüè zhī cí",meaning:"粗略概括的文字。辞只是大概，非全义。"},{id:"gai",term:"该",pinyin:"gāi",meaning:"涵盖、包括。古义「该」通「赅」，完备涵盖。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e(`<h1 id="正易心法·第六章" tabindex="-1">正易心法·第六章 <a class="header-anchor" href="#正易心法·第六章" aria-label="Permalink to &quot;正易心法·第六章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是前五章理论的<strong>第一次方法论示范</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前五章（理论）：卦画是本，文辞是末；要知落处，辞外见意</span></span>
<span class="line"><span>第六章（实践）：具体示范「辞外见意」怎么操作</span></span>
<span class="line"><span>              用大有、大壮、乾、师四个卦做例子</span></span></code></pre></div><p><strong>核心命题：文辞是卦义的截面，卦画是卦义的全体。</strong></p><blockquote><p>就像用一张照片描述一个人——照片能捕捉某一瞬间，但人的全部生命不在照片里。<strong>卦辞是照片，卦画是活生生的人。</strong></p></blockquote><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「大略之辞」的信息量问题</strong>——麻衣举了一个极好的例子：</p><table tabindex="0"><thead><tr><th>卦</th><th>结构</th><th>象</th><th>卦辞</th></tr></thead><tbody><tr><td>大有</td><td>上离下乾</td><td>日在天上</td><td><strong>元亨</strong>（两字）</td></tr><tr><td>大壮</td><td>上震下乾</td><td>雷在天上</td><td><strong>利贞</strong>（两字）</td></tr></tbody></table><p>两卦的处境、警示、应用场景截然不同，<strong>但卦辞都只有两个字</strong>——这两个字能区分这两卦的不同吗？显然不能。</p><p><strong>所以「辞外见意」不是锦上添花，而是读懂卦的必要条件。</strong></p><p><strong>「辟师」的解读</strong>——麻衣对师卦的象数解读极为精彩：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>辟（君主）对应上卦坤——坤为地，为顺，为静</span></span>
<span class="line"><span>师（军队）对应下卦坎——坎为水，为险，为动</span></span>
<span class="line"><span>合则为师 = 外静内动，以静制动</span></span></code></pre></div><p>这与《道德经》「上善若水」、《孙子兵法》「兵无常形，水无常势」高度吻合——<strong>麻衣在这里暗示：兵法、道家、易学，本是同一个卦画的不同语言。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先看大有、大壮两卦的<strong>卦画</strong>，再看它们只有两字的<strong>卦辞</strong>，体会落差；</li><li>读乾卦九二、上九时，<strong>把「龙」还原成「阳气的运动」</strong>；</li><li>师卦那一段是可以直接用的——<strong>外静内动，看看能不能安到自己手上的事。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>无止于辞</strong>：卦画之义不能被文辞穷尽。</li><li><strong>大略之辞</strong>：辞只是粗略概括。</li><li><strong>数字岂能尽义</strong>：元亨、利贞不足以区分两卦。</li><li><strong>辞外之意</strong>：乾之见龙、亢龙是说阳气的消息，不是讲龙。</li><li><strong>辟师之喻</strong>：上坤不动如地，下坎趋变如水——外静内动。</li><li><strong>不可概举</strong>：辞是截面，画是全体。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,19)),s(r,{colophon:"无止于辞 · 辞外见意 · 大略之辞 · 外静内动",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第六章原文",sections:o,glossary:i}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如「易曰」作「易曰」、「该」通「赅」），不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"辞外见意",pinyin:["cí","wài"],meaning:"在文辞之外看到意涵。超越文字，直观卦画深意——本章的方法论核心。"},{term:"大略之辞",pinyin:["dà","lüè"],meaning:"粗略概括的文字。辞只是大概，非全义。"},{term:"大有 · 大壮",pinyin:["dà","yǒu"],meaning:"大有䷍（上离下乾，日在天上）辞「元亨」；大壮䷡（上震下乾，雷在天上）辞「利贞」。结构迥异而辞皆两字。"},{term:"辟师",pinyin:["pì","shī"],meaning:"辟为君主，师为军队。师卦上坤下坎：上不动如地，内趋变如水——外静内动，用兵之极。"},{term:"该",pinyin:["gāi"],meaning:"通「赅」，完备涵盖。「辞之所不能该」即文辞不能完全涵盖。"}]}),t[3]||(t[3]=e('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是前五章理论的<strong>第一次方法论示范</strong>：不要停在辞上，要在辞外见意。</p><p><strong>核心命题：文辞是卦义的截面，卦画是卦义的全体。</strong> 卦辞是照片，卦画是活人。</p><h3 id="理-为什么要这样说" tabindex="-1">理：为什么要这样说 <a class="header-anchor" href="#理-为什么要这样说" aria-label="Permalink to &quot;理：为什么要这样说&quot;">​</a></h3><p><strong>「大略之辞」的信息量问题</strong>：大有（日在天上）与大壮（雷在天上），结构、处境、警示全不同，卦辞却都只有两个字——<strong>这两个字不足以区分这两卦</strong>，所以「辞外见意」是读懂卦的必要条件。</p><p><strong>「辟师」之喻</strong>：上坤（静如地）下坎（动如水）——<strong>外静内动</strong>，正是用兵之道的最高境界。麻衣暗示：<strong>兵法、道家、易学，本是同一个卦画的不同语言。</strong></p><p><strong>与《彖传》的比较</strong>：</p><table tabindex="0"><thead><tr><th>比较点</th><th>《彖传》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>解释路径</td><td>从卦画→义理→文字</td><td>直接从卦画读取</td></tr><tr><td>终点</td><td>落在文字义理上</td><td>落在卦画象上</td></tr><tr><td>信息量</td><td>比卦辞丰富，但仍是截面</td><td>指向无穷，不可概举</td></tr></tbody></table><p><strong>一个关键洞察</strong>：《彖传》其实已经在做「辞外见意」的工作——孔子写《彖传》，正因为卦辞太简略。<strong>但《彖传》是用更多的文字来补文字的不足，这是用椟补椟，不是找回珠。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>拿大有、大壮两卦做练习：<strong>把卦辞放在一边，只看卦画，读出它自己的意思</strong>；</li><li>师卦那段可以直接用：<strong>外静内动</strong>；</li><li>记住一句自问：<strong>我读卦，是在读照片，还是在看活人？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>卦画中阴阳消息的道理，不止步于文辞；能在文辞之外看到意涵，才算真正明察《易》道。</p><p>系在卦上的文辞，只不过是对吉凶的粗略概括，并非说六爻卦画的全部意义就尽于此。</p><p>比如大有卦只系了「元亨」两字，大壮卦只系了「利贞」两字——这几个字，真的足以穷尽这两卦的全部意义吗？必须要在文辞之外看到意涵才行。</p><p>辞外之意，比如乾卦九二「见龙在田」、上九「亢龙有悔」；又如师卦，上卦坤不动如大地，下卦坎内趋变动如流水——这些无穷的妙义，不可一一列举，都是文辞所不能完全涵盖的。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第六章把前面五章的道理想清楚了，还不够——<strong>它第一次动手做了示范：把辞放在一边，只看画。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「大略之辞」</strong>——「元亨」「利贞」这样的辞，是最要紧还是最不要紧？<strong>它是一扇门，还是一堵墙？</strong></li><li><strong>照片与活人</strong>——同一张照片，在不同人眼里读出不同的东西；同一个卦画，在不同情境下有不同的落处。<strong>这是「无穷」的真正含义。</strong></li><li><strong>「辟师」之喻</strong>——上坤静、下坎动，外静内动。<strong>这一条可以直接用在做事上：</strong> 我手上的事，哪一部分该「不动如地」，哪一部分该「趋变如水」？</li><li><strong>「用椟补椟」</strong>——《彖传》用更多文字补文字之不足。<strong>我平时解释一件事，是不是也在「用椟补椟」？</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的思考）：古人说「只可意会不可言传」，但若不言传、不记录，这些妙义又如何流传？——<strong>我的看法是：不必跟随古人的立场，皆为我所用，『知其神而神，不知不神之所以神也』。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 执辞忘象之弊（本章是正面示范）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-07">第七章 · 天地万物</a> — 卦脉：本章「辞外见意」的下一步</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「书不尽言，言不尽意」：与本章同调，但麻衣更彻底</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「乾健坤顺」等八个字，正是本章批评的「大略之辞」</li></ul>',23))])}}});export{y as __pageData,f as default};
